function kSum(nums, k) {
  let maxSum = 0;
  const costs = [];
  for (const num of nums) {
    if (num > 0) maxSum += num;
    costs.push(Math.abs(num));
  }
  costs.sort((a, b) => a - b);

  const heap = [];
  const push = (item) => {
    heap.push(item);
    let i = heap.length - 1;
    while (i > 0) {
      const parent = (i - 1) >> 1;
      if (heap[parent][0] <= heap[i][0]) break;
      [heap[parent], heap[i]] = [heap[i], heap[parent]];
      i = parent;
    }
  };
  const pop = () => {
    const top = heap[0];
    const last = heap.pop();
    if (heap.length === 0) return top;
    heap[0] = last;
    let i = 0;
    while (true) {
      const left = 2 * i + 1;
      const right = left + 1;
      let smallest = i;
      if (left < heap.length && heap[left][0] < heap[smallest][0]) smallest = left;
      if (right < heap.length && heap[right][0] < heap[smallest][0]) smallest = right;
      if (smallest === i) break;
      [heap[smallest], heap[i]] = [heap[i], heap[smallest]];
      i = smallest;
    }
    return top;
  };

  push([costs[0], 0]);
  let removed = 0;
  for (let step = 1; step < k; step++) {
    const [cost, index] = pop();
    removed = cost;
    if (index + 1 < costs.length) {
      push([cost + costs[index + 1], index + 1]);
      push([cost - costs[index] + costs[index + 1], index + 1]);
    }
  }
  return maxSum - removed;
}

