function kSum(nums, k) {
  // List every subsequence sum by doubling the list for each element, then sort from largest to smallest.
  let sums = [0];
  for (const value of nums) sums = sums.concat(sums.map(total => total + value));
  sums.sort((a, b) => b - a);
  return sums[k - 1];
}

